ALTER TABLE stock_epoch_operations ADD COLUMN protocol INTEGER NOT NULL DEFAULT 1 CHECK(protocol IN (1,2));
ALTER TABLE stock_epoch_operations ADD COLUMN ordinary_id TEXT;
ALTER TABLE stock_epoch_operations ADD COLUMN role_id INTEGER;
ALTER TABLE stock_epoch_operations ADD COLUMN role_code TEXT;
ALTER TABLE stock_epoch_operations ADD COLUMN role_permissions TEXT;
ALTER TABLE stock_epoch_operations ADD COLUMN actor_name TEXT;
ALTER TABLE stock_epoch_segments ADD COLUMN source_id TEXT REFERENCES stock_epoch_sources(id);
ALTER TABLE stock_epoch_segments ADD COLUMN branch_id INTEGER REFERENCES branches(id);
ALTER TABLE stock_epoch_segments ADD COLUMN parent_segment_id TEXT;
CREATE TABLE stock_epoch_operation_contracts(operation_id TEXT PRIMARY KEY REFERENCES stock_epoch_operations(id),request_digest TEXT NOT NULL,ordinary_receipt_json TEXT NOT NULL CHECK(json_valid(ordinary_receipt_json)),audit_id INTEGER NOT NULL UNIQUE REFERENCES audit_logs(id));
CREATE TABLE stock_epoch_source_states(event_id TEXT PRIMARY KEY REFERENCES stock_epoch_events(id),source_id TEXT NOT NULL REFERENCES stock_epoch_sources(id),funding_generation INTEGER NOT NULL CHECK(typeof(funding_generation)='integer' AND funding_generation>=0),
gross4 INTEGER NOT NULL CHECK(typeof(gross4)='integer' AND gross4 BETWEEN 0 AND 1000000000000000),paid4 INTEGER NOT NULL CHECK(typeof(paid4)='integer' AND paid4 BETWEEN 0 AND 1000000000000000),debt4 INTEGER NOT NULL CHECK(typeof(debt4)='integer' AND debt4 BETWEEN 0 AND 1000000000000000),credit4 INTEGER NOT NULL CHECK(typeof(credit4)='integer' AND credit4 BETWEEN 0 AND 1000000000000000),asset4 INTEGER NOT NULL CHECK(typeof(asset4)='integer' AND asset4 BETWEEN 0 AND 1000000000000000),cash_in4 INTEGER NOT NULL CHECK(typeof(cash_in4)='integer' AND cash_in4 BETWEEN 0 AND 1000000000000000),cash_out4 INTEGER NOT NULL CHECK(typeof(cash_out4)='integer' AND cash_out4 BETWEEN 0 AND 1000000000000000),shipping4 INTEGER NOT NULL CHECK(typeof(shipping4)='integer' AND shipping4 BETWEEN 0 AND 1000000000000000),
sellable_quantity TEXT NOT NULL CHECK(CAST(sellable_quantity AS REAL)>=0),held_quantity TEXT NOT NULL CHECK(CAST(held_quantity AS REAL)>=0),disposed_quantity TEXT NOT NULL CHECK(CAST(disposed_quantity AS REAL)>=0),consumed_quantity TEXT NOT NULL CHECK(CAST(consumed_quantity AS REAL)>=0),
sellable_net4 INTEGER NOT NULL CHECK(typeof(sellable_net4)='integer' AND sellable_net4 BETWEEN 0 AND 1000000000000000),held_net4 INTEGER NOT NULL CHECK(typeof(held_net4)='integer' AND held_net4 BETWEEN 0 AND 1000000000000000),loss4 INTEGER NOT NULL CHECK(typeof(loss4)='integer' AND loss4 BETWEEN 0 AND 1000000000000000),loss_recovery4 INTEGER NOT NULL CHECK(typeof(loss_recovery4)='integer' AND loss_recovery4 BETWEEN 0 AND 1000000000000000),consumed_cost4 INTEGER NOT NULL CHECK(typeof(consumed_cost4)='integer' AND consumed_cost4 BETWEEN 0 AND 1000000000000000),consumed_recovery4 INTEGER NOT NULL CHECK(typeof(consumed_recovery4)='integer' AND consumed_recovery4 BETWEEN 0 AND 1000000000000000),pending4 INTEGER NOT NULL CHECK(typeof(pending4)='integer' AND pending4 BETWEEN 0 AND 1000000000000000),
CHECK(gross4=paid4+debt4+credit4-asset4-cash_in4),CHECK(gross4=sellable_net4+held_net4+loss4-loss_recovery4+consumed_cost4-consumed_recovery4+credit4),CHECK(loss_recovery4<=loss4 AND consumed_recovery4<=consumed_cost4 AND credit4<=gross4));
CREATE TABLE stock_epoch_source_heads(source_id TEXT PRIMARY KEY REFERENCES stock_epoch_sources(id),event_id TEXT NOT NULL UNIQUE REFERENCES stock_epoch_source_states(event_id),revision INTEGER NOT NULL,funding_generation INTEGER NOT NULL,dataset_generation INTEGER NOT NULL);
CREATE TABLE stock_epoch_current_fragments(source_id TEXT NOT NULL REFERENCES stock_epoch_sources(id),segment_id TEXT NOT NULL,event_id TEXT NOT NULL,allocation_id TEXT NOT NULL,branch_id INTEGER NOT NULL REFERENCES branches(id),fate TEXT NOT NULL,assignment_id TEXT UNIQUE REFERENCES stock_epoch_assignments(id),PRIMARY KEY(source_id,segment_id),FOREIGN KEY(event_id,segment_id) REFERENCES stock_epoch_segments(event_id,segment_id));
CREATE INDEX stock_epoch_current_eligible ON stock_epoch_current_fragments(source_id,branch_id,segment_id) WHERE fate='sellable';
CREATE INDEX stock_epoch_current_lineage ON stock_epoch_current_fragments(source_id,allocation_id,segment_id);
CREATE TABLE stock_epoch_lot_heads(batch_id INTEGER NOT NULL REFERENCES product_batches(id),branch_id INTEGER NOT NULL REFERENCES branches(id),product_id INTEGER NOT NULL REFERENCES products(id),operation_id TEXT NOT NULL REFERENCES stock_epoch_operations(id),quantity TEXT NOT NULL,received_quantity TEXT NOT NULL,received_gross4 INTEGER NOT NULL CHECK(typeof(received_gross4)='integer' AND received_gross4 BETWEEN 0 AND 1000000000000000),dataset_generation INTEGER NOT NULL,PRIMARY KEY(batch_id,branch_id));
CREATE TABLE stock_epoch_lot_effects(operation_id TEXT NOT NULL REFERENCES stock_epoch_operations(id),line_id TEXT NOT NULL,product_id INTEGER NOT NULL REFERENCES products(id),branch_id INTEGER NOT NULL REFERENCES branches(id),batch_id INTEGER REFERENCES product_batches(id),batch_key TEXT NOT NULL,previous_operation_id TEXT REFERENCES stock_epoch_operations(id),quantity_before TEXT NOT NULL,quantity_after TEXT NOT NULL,received_before TEXT NOT NULL,received_after TEXT NOT NULL,gross_before4 INTEGER NOT NULL CHECK(typeof(gross_before4)='integer' AND gross_before4 BETWEEN 0 AND 1000000000000000),gross_after4 INTEGER NOT NULL CHECK(typeof(gross_after4)='integer' AND gross_after4 BETWEEN 0 AND 1000000000000000),branch_before REAL NOT NULL,branch_after REAL NOT NULL,product_before REAL NOT NULL,product_after REAL NOT NULL,PRIMARY KEY(operation_id,line_id),UNIQUE(operation_id,product_id,branch_id,batch_key));

CREATE TRIGGER stock_epoch_protocol_actor BEFORE INSERT ON stock_epoch_operations WHEN NEW.protocol=2 AND (NEW.kind NOT IN ('stock_session','hold','repair') OR NEW.ordinary_id IS NULL OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN roles r ON r.id=u.role_id WHERE u.id=NEW.actor_id AND u.is_active=1 AND u.deleted_at IS NULL AND u.permissions IS NEW.actor_permissions AND u.role_id IS NEW.role_id AND r.code IS NEW.role_code AND r.permissions IS NEW.role_permissions) OR NEW.dataset_generation<>(SELECT generation FROM stock_epoch_dataset WHERE singleton=1) OR EXISTS(SELECT 1 FROM system_flags WHERE key='maintenance')) BEGIN SELECT RAISE(ABORT,'epoch operation authority'); END;

CREATE TRIGGER stock_epoch_lot_effect_preimage BEFORE INSERT ON stock_epoch_lot_effects WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_operations o JOIN products p ON p.id=NEW.product_id JOIN branch_stock b ON b.product_id=p.id AND b.branch_id=NEW.branch_id WHERE o.id=NEW.operation_id AND o.protocol=2 AND o.kind='stock_session' AND NOT EXISTS(SELECT 1 FROM stock_epoch_publications x WHERE x.operation_id=o.id) AND p.stock_quantity=NEW.product_before AND b.quantity=NEW.branch_before AND o.dataset_generation=(SELECT generation FROM stock_epoch_dataset WHERE singleton=1) AND ((NEW.batch_id IS NULL AND NEW.previous_operation_id IS NULL AND NEW.quantity_before='0' AND NEW.received_before='0' AND NEW.gross_before4=0 AND NOT EXISTS(SELECT 1 FROM product_batches z WHERE z.variant_product_id=NEW.product_id AND z.batch_key=NEW.batch_key)) OR EXISTS(SELECT 1 FROM stock_epoch_lot_heads h JOIN product_batches pb ON pb.id=h.batch_id JOIN branch_batch_stock bs ON bs.batch_id=pb.id AND bs.branch_id=h.branch_id WHERE h.batch_id=NEW.batch_id AND h.branch_id=NEW.branch_id AND h.product_id=NEW.product_id AND h.operation_id=NEW.previous_operation_id AND pb.batch_key=NEW.batch_key AND h.quantity=NEW.quantity_before AND h.received_quantity=NEW.received_before AND h.received_gross4=NEW.gross_before4 AND bs.quantity=CAST(h.quantity AS REAL) AND pb.received_quantity=CAST(h.received_quantity AS REAL) AND pb.received_cost_usd=h.received_gross4/10000.0))) BEGIN SELECT RAISE(ABORT,'epoch lot preimage'); END;

CREATE VIEW stock_epoch_receipt_members AS SELECT o.id AS operation_id,o.ordinary_id,o.actor_id,m.line_id,m.movement_id,m.product_id,m.branch_id,m.batch_id,m.quantity,m.unit_cost_usd,json_extract(j.value,'$.payment_status') AS payment_status,json_extract(j.value,'$.supplier_id') AS supplier_id,json_extract(j.value,'$.quantity') AS request_quantity,json_extract(j.value,'$.unit_cost_usd') AS request_unit_cost FROM stock_epoch_operations o JOIN stock_session_operations s ON s.id=o.ordinary_id JOIN stock_session_members m ON m.operation_id=s.id JOIN json_each(s.request_json,'$.items') j ON json_extract(j.value,'$.line_id')=m.line_id WHERE o.protocol=2 AND o.kind='stock_session' AND m.quantity>0;

CREATE TRIGGER stock_epoch_source_receipt BEFORE INSERT ON stock_epoch_sources WHEN EXISTS(SELECT 1 FROM stock_epoch_operations o WHERE o.id=NEW.admission_operation_id AND o.protocol=2) AND NOT EXISTS(SELECT 1 FROM stock_epoch_receipt_members m JOIN stock_session_operations p ON p.id=m.ordinary_id JOIN inventory_movements v ON v.id=m.movement_id JOIN suppliers supplier ON supplier.id=m.supplier_id WHERE m.operation_id=NEW.admission_operation_id AND m.movement_id=NEW.movement_id AND m.product_id=NEW.product_id AND m.branch_id=NEW.branch_id AND m.batch_id=NEW.batch_id AND m.supplier_id=NEW.supplier_id AND m.quantity=m.request_quantity AND m.quantity=CAST(NEW.quantity AS REAL) AND m.unit_cost_usd=m.request_unit_cost AND v.product_id=m.product_id AND v.batch_id=m.batch_id AND v.branch_id=m.branch_id AND v.quantity=m.quantity AND COALESCE(v.free_quantity,0)=0 AND NEW.free_quantity='0' AND v.movement_type='add' AND v.total_cost_usd=NEW.gross4/10000.0 AND typeof(NEW.opening_paid4)='integer' AND typeof(NEW.opening_debt4)='integer' AND NEW.opening_paid4=CASE m.payment_status WHEN 'paid' THEN NEW.gross4 ELSE 0 END AND NEW.opening_debt4=CASE m.payment_status WHEN 'credit' THEN NEW.gross4 ELSE 0 END AND m.payment_status IN ('paid','credit') AND NEW.invoice_id IS NULL AND NEW.actor_id=m.actor_id AND p.actor_id=m.actor_id AND p.request_json=(SELECT request_json FROM stock_epoch_operations WHERE id=m.operation_id) AND NOT EXISTS(SELECT 1 FROM supplier_invoices i WHERE (i.supplier_id=m.supplier_id OR i.supplier_id IS NULL) AND (i.branch_id=m.branch_id OR i.branch_id IS NULL))) BEGIN SELECT RAISE(ABORT,'epoch receipt source mismatch'); END;

CREATE TRIGGER stock_epoch_state_identity BEFORE INSERT ON stock_epoch_source_states WHEN (NOT EXISTS(SELECT 1 FROM stock_epoch_events e JOIN stock_epoch_operations o ON o.id=e.operation_id JOIN stock_epoch_sources s ON s.id=e.source_id WHERE e.id=NEW.event_id AND e.source_id=NEW.source_id AND e.funding_generation=NEW.funding_generation AND o.protocol=2 AND e.kind='admit' AND e.revision=0 AND NEW.gross4=s.gross4 AND NEW.paid4=s.opening_paid4 AND NEW.debt4=s.opening_debt4 AND NEW.credit4=0 AND NEW.asset4=0 AND NEW.cash_in4=0 AND NEW.cash_out4=0 AND NEW.shipping4=0 AND NEW.pending4=0 AND NEW.sellable_quantity=s.quantity AND NEW.held_quantity='0' AND NEW.disposed_quantity='0' AND NEW.consumed_quantity='0' AND NEW.sellable_net4=s.gross4 AND NEW.held_net4=0 AND NEW.loss4=0 AND NEW.loss_recovery4=0 AND NEW.consumed_cost4=0 AND NEW.consumed_recovery4=0 AND e.funding_json=json_object('gross4',NEW.gross4,'paid4',NEW.paid4,'debt4',NEW.debt4,'credit4',NEW.credit4,'asset4',NEW.asset4,'cash_in4',NEW.cash_in4,'cash_out4',NEW.cash_out4,'shipping4',NEW.shipping4))) AND NOT EXISTS(SELECT 1 FROM stock_epoch_events e JOIN stock_epoch_operations o ON o.id=e.operation_id JOIN stock_epoch_commands c ON c.operation_id=o.id JOIN stock_epoch_source_states v ON v.event_id=c.before_event_id WHERE e.id=NEW.event_id AND e.source_id=NEW.source_id AND v.source_id=NEW.source_id AND o.protocol=2 AND o.kind IN ('hold','repair') AND e.kind=o.kind AND NEW.funding_generation=v.funding_generation AND NEW.gross4=v.gross4 AND NEW.paid4=v.paid4 AND NEW.debt4=v.debt4 AND NEW.credit4=v.credit4 AND NEW.asset4=v.asset4 AND NEW.cash_in4=v.cash_in4 AND NEW.cash_out4=v.cash_out4 AND NEW.shipping4=v.shipping4 AND NEW.pending4=v.pending4 AND e.funding_json=(SELECT funding_json FROM stock_epoch_events WHERE id=c.before_event_id)) BEGIN SELECT RAISE(ABORT,'epoch typed source state'); END;

CREATE TRIGGER stock_epoch_source_head_owned BEFORE INSERT ON stock_epoch_source_heads WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_events e JOIN stock_epoch_source_states s ON s.event_id=e.id JOIN stock_epoch_operations o ON o.id=e.operation_id WHERE e.id=NEW.event_id AND e.source_id=NEW.source_id AND s.source_id=NEW.source_id AND e.revision=NEW.revision AND e.funding_generation=NEW.funding_generation AND o.protocol=2 AND o.dataset_generation=NEW.dataset_generation AND NOT EXISTS(SELECT 1 FROM stock_epoch_publications p WHERE p.operation_id=o.id)) BEGIN SELECT RAISE(ABORT,'epoch source head unowned'); END;
CREATE TRIGGER stock_epoch_fragment_head_owned BEFORE INSERT ON stock_epoch_current_fragments WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_segments s JOIN stock_epoch_events e ON e.id=s.event_id JOIN stock_epoch_operations o ON o.id=e.operation_id WHERE s.event_id=NEW.event_id AND s.segment_id=NEW.segment_id AND s.source_id=NEW.source_id AND e.source_id=NEW.source_id AND s.allocation_id=NEW.allocation_id AND s.branch_id=NEW.branch_id AND s.fate=NEW.fate AND s.consumption_id IS NEW.assignment_id AND o.protocol=2 AND NOT EXISTS(SELECT 1 FROM stock_epoch_publications p WHERE p.operation_id=o.id)) BEGIN SELECT RAISE(ABORT,'epoch fragment head unowned'); END;

CREATE TRIGGER stock_epoch_lot_head_insert BEFORE INSERT ON stock_epoch_lot_heads WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_lot_effects f JOIN stock_epoch_operations o ON o.id=f.operation_id JOIN stock_session_members m ON m.operation_id=o.ordinary_id AND m.line_id=f.line_id WHERE f.operation_id=NEW.operation_id AND m.batch_id=NEW.batch_id AND f.product_id=NEW.product_id AND f.branch_id=NEW.branch_id AND f.quantity_after=NEW.quantity AND f.received_after=NEW.received_quantity AND f.gross_after4=NEW.received_gross4 AND o.dataset_generation=NEW.dataset_generation AND o.protocol=2 AND NOT EXISTS(SELECT 1 FROM stock_epoch_publications p WHERE p.operation_id=o.id)) BEGIN SELECT RAISE(ABORT,'epoch lot head unowned'); END;
CREATE TRIGGER stock_epoch_lot_head_update BEFORE UPDATE ON stock_epoch_lot_heads WHEN (NEW.batch_id IS NOT OLD.batch_id OR NEW.branch_id IS NOT OLD.branch_id OR NEW.product_id IS NOT OLD.product_id OR NOT EXISTS(SELECT 1 FROM stock_epoch_lot_effects f JOIN stock_epoch_operations o ON o.id=f.operation_id JOIN stock_session_members m ON m.operation_id=o.ordinary_id AND m.line_id=f.line_id WHERE f.operation_id=NEW.operation_id AND m.batch_id=NEW.batch_id AND f.product_id=NEW.product_id AND f.branch_id=NEW.branch_id AND f.quantity_after=NEW.quantity AND f.received_after=NEW.received_quantity AND f.gross_after4=NEW.received_gross4 AND o.dataset_generation=NEW.dataset_generation AND o.protocol=2 AND NOT EXISTS(SELECT 1 FROM stock_epoch_publications p WHERE p.operation_id=o.id)) OR NOT EXISTS(SELECT 1 FROM stock_epoch_lot_effects f WHERE f.operation_id=NEW.operation_id AND f.previous_operation_id=OLD.operation_id AND f.quantity_before=OLD.quantity AND f.received_before=OLD.received_quantity AND f.gross_before4=OLD.received_gross4 AND f.branch_id=OLD.branch_id AND f.product_id=OLD.product_id AND f.batch_id=OLD.batch_id)) AND NOT EXISTS(SELECT 1 FROM stock_epoch_commands c JOIN stock_epoch_operations o ON o.id=c.operation_id WHERE c.operation_id=NEW.operation_id AND o.protocol=2 AND o.kind IN ('hold','repair') AND c.batch_id=OLD.batch_id AND c.branch_id=OLD.branch_id AND c.product_id=OLD.product_id AND c.previous_lot_operation_id=OLD.operation_id AND NEW.batch_id=OLD.batch_id AND NEW.branch_id=OLD.branch_id AND NEW.product_id=OLD.product_id AND CAST(OLD.quantity AS REAL)=CAST(c.quantity_before AS REAL) AND CAST(NEW.quantity AS REAL)=CAST(c.quantity_after AS REAL) AND NEW.received_quantity=OLD.received_quantity AND NEW.received_gross4=OLD.received_gross4 AND NEW.dataset_generation=OLD.dataset_generation AND NOT EXISTS(SELECT 1 FROM stock_epoch_publications p WHERE p.operation_id=o.id)) BEGIN SELECT RAISE(ABORT,'epoch lot head preimage'); END;
CREATE TRIGGER stock_epoch_lot_head_delete BEFORE DELETE ON stock_epoch_lot_heads BEGIN SELECT RAISE(ABORT,'epoch lot head immutable'); END;

DROP TRIGGER stock_lifecycle_batch_update;
CREATE TRIGGER stock_lifecycle_batch_update BEFORE UPDATE ON product_batches
 WHEN EXISTS(SELECT 1 FROM stock_lifecycle_dependencies WHERE batch_id=OLD.id) AND (NEW.id IS NOT OLD.id OR NEW.variant_product_id IS NOT OLD.variant_product_id OR NEW.received_at IS NOT OLD.received_at OR NEW.received_quantity IS NOT OLD.received_quantity OR NEW.received_cost_usd IS NOT OLD.received_cost_usd OR NEW.received_branch_id IS NOT OLD.received_branch_id OR NEW.supplier_id IS NOT OLD.supplier_id OR NEW.supplier_name IS NOT OLD.supplier_name OR NEW.payment_status IS NOT OLD.payment_status OR NEW.credit_due_date IS NOT OLD.credit_due_date OR NEW.unit_cost_usd IS NOT OLD.unit_cost_usd OR NEW.is_active IS NOT OLD.is_active OR NEW.batch_key IS NOT OLD.batch_key OR NEW.lot_code IS NOT OLD.lot_code)
 AND NOT EXISTS(SELECT 1 FROM stock_epoch_lot_effects f JOIN stock_epoch_operations o ON o.id=f.operation_id LEFT JOIN stock_epoch_publications p ON p.operation_id=o.id WHERE o.protocol=2 AND o.kind='stock_session' AND p.operation_id IS NULL AND f.batch_id=OLD.id AND f.product_id=OLD.variant_product_id AND CAST(f.received_before AS REAL)=OLD.received_quantity AND CAST(f.received_after AS REAL)=NEW.received_quantity AND f.gross_before4/10000.0=OLD.received_cost_usd AND f.gross_after4/10000.0=NEW.received_cost_usd AND NEW.id IS OLD.id AND NEW.variant_product_id IS OLD.variant_product_id AND NEW.received_at IS OLD.received_at AND NEW.received_branch_id IS OLD.received_branch_id AND NEW.supplier_id IS OLD.supplier_id AND NEW.supplier_name IS OLD.supplier_name AND NEW.payment_status IS OLD.payment_status AND NEW.credit_due_date IS OLD.credit_due_date AND NEW.unit_cost_usd IS OLD.unit_cost_usd AND NEW.is_active IS OLD.is_active AND NEW.batch_key IS OLD.batch_key AND NEW.lot_code IS OLD.lot_code)
 BEGIN SELECT RAISE(ABORT,'stock_lifecycle_dependency'); END;

DROP TRIGGER stock_lifecycle_lot_update;
CREATE TRIGGER stock_lifecycle_lot_update BEFORE UPDATE ON branch_batch_stock
 WHEN EXISTS(SELECT 1 FROM stock_lifecycle_dependencies WHERE batch_id=OLD.batch_id) AND (NEW.quantity IS NOT OLD.quantity OR NEW.batch_id IS NOT OLD.batch_id OR NEW.branch_id IS NOT OLD.branch_id)
 AND NOT EXISTS(SELECT 1 FROM stock_lifecycle_context x JOIN stock_disposition_guards g ON g.token=x.token WHERE g.valid=1 AND x.batch_id=OLD.batch_id AND x.branch_id=OLD.branch_id AND NEW.batch_id=OLD.batch_id AND NEW.branch_id=OLD.branch_id AND NEW.quantity=x.remaining_quantity)
 AND NOT EXISTS(SELECT 1 FROM stock_valuation_context x JOIN stock_valuation_guards g ON g.token=x.token WHERE g.valid=1 AND x.batch_id=OLD.batch_id AND x.branch_id=OLD.branch_id AND NEW.batch_id=OLD.batch_id AND NEW.branch_id=OLD.branch_id AND NEW.quantity=x.remaining_quantity AND ((x.operation_id IS NULL AND NOT EXISTS(SELECT 1 FROM stock_valuation_events_v4 e WHERE e.source_id=x.source_id)) OR EXISTS(SELECT 1 FROM stock_valuation_latest e WHERE e.id=x.operation_id AND e.source_id=x.source_id AND e.schema_version=4 AND (e.kind NOT IN ('consume','restore','reconsume') OR EXISTS(SELECT 1 FROM stock_valuation_sale_operation_context op WHERE op.token=x.token AND op.event_id=e.id AND op.source_id=e.source_id AND op.remaining_quantity=NEW.quantity)))))
 AND NOT EXISTS(SELECT 1 FROM stock_epoch_lot_effects f JOIN stock_epoch_operations o ON o.id=f.operation_id LEFT JOIN stock_epoch_publications p ON p.operation_id=o.id WHERE o.protocol=2 AND o.kind='stock_session' AND p.operation_id IS NULL AND f.batch_id=OLD.batch_id AND f.branch_id=OLD.branch_id AND NEW.batch_id=OLD.batch_id AND NEW.branch_id=OLD.branch_id AND CAST(f.quantity_before AS REAL)=OLD.quantity AND CAST(f.quantity_after AS REAL)=NEW.quantity)
 AND NOT EXISTS(SELECT 1 FROM stock_epoch_commands c JOIN stock_epoch_operations o ON o.id=c.operation_id WHERE o.protocol=2 AND o.kind IN ('hold','repair') AND c.batch_id=OLD.batch_id AND c.branch_id=OLD.branch_id AND NEW.batch_id=OLD.batch_id AND NEW.branch_id=OLD.branch_id AND OLD.quantity=CAST(c.quantity_before AS REAL) AND NEW.quantity=CAST(c.quantity_after AS REAL) AND NOT EXISTS(SELECT 1 FROM stock_epoch_publications p WHERE p.operation_id=o.id))
 BEGIN SELECT RAISE(ABORT,'stock_lifecycle_dependency'); END;

DROP TRIGGER stock_lifecycle_lot_insert;
CREATE TRIGGER stock_lifecycle_lot_insert BEFORE INSERT ON branch_batch_stock
 WHEN EXISTS(SELECT 1 FROM stock_lifecycle_dependencies WHERE batch_id=NEW.batch_id)
 AND NOT EXISTS(SELECT 1 FROM branch_batch_stock b JOIN stock_valuation_context c ON c.batch_id=b.batch_id AND c.branch_id=b.branch_id JOIN stock_valuation_guards g ON g.token=c.token AND g.valid=1 JOIN stock_valuation_sale_operation_context op ON op.token=c.token AND op.event_id=c.operation_id JOIN stock_valuation_latest e ON e.id=op.event_id AND e.source_id=op.source_id JOIN stock_valuation_sale_links l ON l.id=op.consumption_id AND l.source_id=op.source_id AND l.sale_allocation_id=op.sale_allocation_id JOIN sale_item_batch_allocations a ON a.id=l.sale_allocation_id JOIN stock_funding_sources f ON f.id=l.source_id WHERE b.batch_id=NEW.batch_id AND b.branch_id=NEW.branch_id AND f.batch_id=b.batch_id AND f.branch_id=b.branch_id AND c.source_id=f.id AND a.batch_id=b.batch_id AND a.branch_id=b.branch_id AND op.kind='restore' AND e.kind='restore' AND e.schema_version=4 AND a.released_quantity=op.released_before AND op.released_before=0 AND op.released_after=a.quantity AND a.quantity=CAST(l.quantity AS REAL) AND NEW.quantity=a.quantity AND b.quantity+NEW.quantity=op.remaining_quantity AND c.remaining_quantity=op.remaining_quantity)
 AND NOT EXISTS(SELECT 1 FROM stock_epoch_lot_effects f JOIN stock_epoch_operations o ON o.id=f.operation_id LEFT JOIN stock_epoch_publications p ON p.operation_id=o.id JOIN branch_batch_stock b ON b.batch_id=f.batch_id AND b.branch_id=f.branch_id WHERE o.protocol=2 AND o.kind='stock_session' AND p.operation_id IS NULL AND f.batch_id=NEW.batch_id AND f.branch_id=NEW.branch_id AND b.quantity=CAST(f.quantity_before AS REAL) AND b.quantity+NEW.quantity=CAST(f.quantity_after AS REAL))
 BEGIN SELECT RAISE(ABORT,'stock_lifecycle_dependency'); END;

DROP TRIGGER stock_valuation_events_epoch_identity;
CREATE TRIGGER stock_valuation_events_epoch_identity BEFORE INSERT ON stock_valuation_events WHEN EXISTS(SELECT 1 FROM stock_epoch_event_registry WHERE event_id=NEW.id OR (source_id=NEW.source_id AND revision=NEW.revision)) OR NEW.revision<>(SELECT COALESCE(MAX(revision)+1,0) FROM stock_epoch_event_registry WHERE source_id=NEW.source_id) OR EXISTS(SELECT 1 FROM stock_epoch_adoptions WHERE source_id=NEW.source_id) BEGIN SELECT RAISE(ABORT,'valuation_global_identity_conflict'); END;

DROP TRIGGER stock_valuation_events_v4_epoch_identity;
CREATE TRIGGER stock_valuation_events_v4_epoch_identity BEFORE INSERT ON stock_valuation_events_v4 WHEN EXISTS(SELECT 1 FROM stock_epoch_event_registry WHERE event_id=NEW.id OR (source_id=NEW.source_id AND revision=NEW.revision)) OR NEW.revision<>(SELECT COALESCE(MAX(revision)+1,0) FROM stock_epoch_event_registry WHERE source_id=NEW.source_id) OR EXISTS(SELECT 1 FROM stock_epoch_adoptions WHERE source_id=NEW.source_id) BEGIN SELECT RAISE(ABORT,'valuation_global_identity_conflict'); END;

CREATE TRIGGER stock_epoch_operation_sources_closed_insert BEFORE INSERT ON stock_epoch_operation_sources WHEN EXISTS(SELECT 1 FROM stock_epoch_publications WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'epoch publication closed'); END;

CREATE TRIGGER stock_epoch_events_closed_insert BEFORE INSERT ON stock_epoch_events WHEN EXISTS(SELECT 1 FROM stock_epoch_publications WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'epoch publication closed'); END;

CREATE TRIGGER stock_epoch_segments_closed_insert BEFORE INSERT ON stock_epoch_segments WHEN EXISTS(SELECT 1 FROM stock_epoch_publications WHERE operation_id=(SELECT operation_id FROM stock_epoch_events WHERE id=NEW.event_id)) BEGIN SELECT RAISE(ABORT,'epoch publication closed'); END;

CREATE TRIGGER stock_epoch_receipts_closed_insert BEFORE INSERT ON stock_epoch_receipts WHEN EXISTS(SELECT 1 FROM stock_epoch_publications WHERE operation_id=(SELECT operation_id FROM stock_epoch_events WHERE id=NEW.event_id)) BEGIN SELECT RAISE(ABORT,'epoch publication closed'); END;

CREATE TRIGGER stock_epoch_epochs_closed_insert BEFORE INSERT ON stock_epoch_epochs WHEN EXISTS(SELECT 1 FROM stock_epoch_publications WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'epoch publication closed'); END;

CREATE TRIGGER stock_epoch_assignments_closed_insert BEFORE INSERT ON stock_epoch_assignments WHEN EXISTS(SELECT 1 FROM stock_epoch_publications WHERE operation_id=(SELECT operation_id FROM stock_epoch_epochs WHERE id=NEW.epoch_id)) BEGIN SELECT RAISE(ABORT,'epoch publication closed'); END;

CREATE TRIGGER stock_epoch_assignment_changes_closed_insert BEFORE INSERT ON stock_epoch_assignment_changes WHEN EXISTS(SELECT 1 FROM stock_epoch_publications WHERE operation_id=(SELECT operation_id FROM stock_epoch_events WHERE id=NEW.event_id)) BEGIN SELECT RAISE(ABORT,'epoch publication closed'); END;

