CREATE TRIGGER stock_epoch_adoptions_closed_insert BEFORE INSERT ON stock_epoch_adoptions WHEN EXISTS(SELECT 1 FROM stock_epoch_publications WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'epoch publication closed'); END;

CREATE TRIGGER stock_epoch_operation_contracts_closed_insert BEFORE INSERT ON stock_epoch_operation_contracts WHEN EXISTS(SELECT 1 FROM stock_epoch_publications WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'epoch publication closed'); END;

CREATE TRIGGER stock_epoch_source_states_closed_insert BEFORE INSERT ON stock_epoch_source_states WHEN EXISTS(SELECT 1 FROM stock_epoch_publications WHERE operation_id=(SELECT operation_id FROM stock_epoch_events WHERE id=NEW.event_id)) BEGIN SELECT RAISE(ABORT,'epoch publication closed'); END;

CREATE TRIGGER stock_epoch_lot_effects_closed_insert BEFORE INSERT ON stock_epoch_lot_effects WHEN EXISTS(SELECT 1 FROM stock_epoch_publications WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'epoch publication closed'); END;

CREATE TRIGGER stock_epoch_operation_contracts_no_replace BEFORE INSERT ON stock_epoch_operation_contracts WHEN EXISTS(SELECT 1 FROM stock_epoch_operation_contracts WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'epoch immutable identity'); END;

CREATE TRIGGER stock_epoch_operation_contracts_no_update BEFORE UPDATE ON stock_epoch_operation_contracts BEGIN SELECT RAISE(ABORT,'epoch immutable'); END;

CREATE TRIGGER stock_epoch_operation_contracts_no_delete BEFORE DELETE ON stock_epoch_operation_contracts BEGIN SELECT RAISE(ABORT,'epoch immutable'); END;

CREATE TRIGGER stock_epoch_source_states_no_replace BEFORE INSERT ON stock_epoch_source_states WHEN EXISTS(SELECT 1 FROM stock_epoch_source_states WHERE event_id=NEW.event_id) BEGIN SELECT RAISE(ABORT,'epoch immutable identity'); END;

CREATE TRIGGER stock_epoch_source_states_no_update BEFORE UPDATE ON stock_epoch_source_states BEGIN SELECT RAISE(ABORT,'epoch immutable'); END;

CREATE TRIGGER stock_epoch_source_states_no_delete BEFORE DELETE ON stock_epoch_source_states BEGIN SELECT RAISE(ABORT,'epoch immutable'); END;

CREATE TRIGGER stock_epoch_source_heads_no_replace BEFORE INSERT ON stock_epoch_source_heads WHEN EXISTS(SELECT 1 FROM stock_epoch_source_heads WHERE source_id=NEW.source_id) BEGIN SELECT RAISE(ABORT,'epoch immutable identity'); END;

CREATE TRIGGER stock_epoch_source_heads_no_update BEFORE UPDATE ON stock_epoch_source_heads BEGIN SELECT RAISE(ABORT,'epoch immutable'); END;

CREATE TRIGGER stock_epoch_source_heads_no_delete BEFORE DELETE ON stock_epoch_source_heads BEGIN SELECT RAISE(ABORT,'epoch immutable'); END;

CREATE TRIGGER stock_epoch_current_fragments_no_replace BEFORE INSERT ON stock_epoch_current_fragments WHEN EXISTS(SELECT 1 FROM stock_epoch_current_fragments WHERE source_id=NEW.source_id AND segment_id=NEW.segment_id) BEGIN SELECT RAISE(ABORT,'epoch immutable identity'); END;

CREATE TRIGGER stock_epoch_current_fragments_no_update BEFORE UPDATE ON stock_epoch_current_fragments BEGIN SELECT RAISE(ABORT,'epoch immutable'); END;

CREATE TRIGGER stock_epoch_current_fragments_no_delete BEFORE DELETE ON stock_epoch_current_fragments BEGIN SELECT RAISE(ABORT,'epoch immutable'); END;

CREATE TRIGGER stock_epoch_lot_effects_no_replace BEFORE INSERT ON stock_epoch_lot_effects WHEN EXISTS(SELECT 1 FROM stock_epoch_lot_effects WHERE operation_id=NEW.operation_id AND line_id=NEW.line_id) BEGIN SELECT RAISE(ABORT,'epoch immutable identity'); END;

CREATE TRIGGER stock_epoch_lot_effects_no_update BEFORE UPDATE ON stock_epoch_lot_effects BEGIN SELECT RAISE(ABORT,'epoch immutable'); END;

CREATE TRIGGER stock_epoch_lot_effects_no_delete BEFORE DELETE ON stock_epoch_lot_effects BEGIN SELECT RAISE(ABORT,'epoch immutable'); END;

CREATE TRIGGER stock_epoch_publication_protocol2 BEFORE INSERT ON stock_epoch_publications WHEN EXISTS(SELECT 1 FROM stock_epoch_operations WHERE id=NEW.operation_id AND protocol=2 AND kind='stock_session') BEGIN
SELECT CASE WHEN EXISTS(SELECT 1 FROM stock_epoch_operations o JOIN users u ON u.id=o.actor_id LEFT JOIN roles r ON r.id=u.role_id JOIN stock_session_operations s ON s.id=o.ordinary_id JOIN stock_epoch_operation_contracts c ON c.operation_id=o.id JOIN audit_logs a ON a.id=c.audit_id WHERE o.id=NEW.operation_id AND o.kind='stock_session' AND u.is_active=1 AND u.deleted_at IS NULL AND u.permissions IS o.actor_permissions AND u.role_id IS o.role_id AND r.code IS o.role_code AND r.permissions IS o.role_permissions AND o.dataset_generation=(SELECT generation FROM stock_epoch_dataset WHERE singleton=1) AND s.actor_id=o.actor_id AND s.request_json=o.request_json AND s.receipt_json=c.ordinary_receipt_json AND a.user_id=o.actor_id AND a.entity='stock_session' AND a.entity_id=s.id AND a.action='stock_session_create' AND a.details=s.receipt_json AND a.new_value=s.receipt_json AND o.source_count=(SELECT COUNT(*) FROM json_each(s.request_json,'$.items') j WHERE json_extract(j.value,'$.quantity')>0) AND o.source_count=(SELECT COUNT(*) FROM stock_epoch_receipt_members m WHERE m.operation_id=o.id)) THEN 1 ELSE RAISE(ABORT,'epoch ordinary operation incomplete') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_receipt_members m WHERE m.operation_id=NEW.operation_id AND NOT EXISTS(SELECT 1 FROM stock_epoch_sources s JOIN stock_epoch_events e ON e.source_id=s.id JOIN stock_epoch_source_states v ON v.event_id=e.id JOIN stock_epoch_source_heads h ON h.source_id=s.id JOIN stock_epoch_segments g ON g.event_id=e.id JOIN stock_epoch_current_fragments c ON c.source_id=s.id AND c.segment_id=g.segment_id WHERE s.admission_operation_id=m.operation_id AND s.movement_id=m.movement_id AND e.operation_id=m.operation_id AND e.kind='admit' AND v.source_id=s.id AND h.event_id=e.id AND h.revision=e.revision AND h.funding_generation=e.funding_generation AND h.dataset_generation=(SELECT generation FROM stock_epoch_dataset WHERE singleton=1) AND g.segment_id='origin' AND g.source_id=s.id AND g.quantity=s.quantity AND g.gross4=s.gross4 AND g.coverage4=0 AND g.fate='sellable' AND g.consumption_id IS NULL AND g.consumed_cost4=0 AND g.consumed_recovery4=0 AND c.event_id=g.event_id AND c.fate=g.fate AND c.branch_id=m.branch_id)) AND NOT EXISTS(SELECT 1 FROM stock_epoch_sources s WHERE s.admission_operation_id=NEW.operation_id AND NOT EXISTS(SELECT 1 FROM stock_epoch_receipt_members m WHERE m.operation_id=NEW.operation_id AND m.movement_id=s.movement_id)) THEN 1 ELSE RAISE(ABORT,'epoch required source incomplete') END;
SELECT CASE WHEN (SELECT COUNT(*) FROM stock_epoch_segments g JOIN stock_epoch_events e ON e.id=g.event_id WHERE e.operation_id=NEW.operation_id)=(SELECT source_count FROM stock_epoch_operations WHERE id=NEW.operation_id) AND (SELECT COUNT(*) FROM stock_epoch_source_states v JOIN stock_epoch_events e ON e.id=v.event_id WHERE e.operation_id=NEW.operation_id)=(SELECT source_count FROM stock_epoch_operations WHERE id=NEW.operation_id) AND (SELECT COUNT(*) FROM stock_epoch_lot_effects WHERE operation_id=NEW.operation_id)=(SELECT source_count FROM stock_epoch_operations WHERE id=NEW.operation_id) THEN 1 ELSE RAISE(ABORT,'epoch extra or missing child') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_receipt_members m LEFT JOIN stock_epoch_lot_effects f ON f.operation_id=m.operation_id AND f.line_id=m.line_id LEFT JOIN stock_epoch_lot_heads h ON h.batch_id=m.batch_id AND h.branch_id=m.branch_id LEFT JOIN product_batches b ON b.id=m.batch_id LEFT JOIN branch_batch_stock bs ON bs.batch_id=m.batch_id AND bs.branch_id=m.branch_id LEFT JOIN branch_stock a ON a.product_id=m.product_id AND a.branch_id=m.branch_id LEFT JOIN products p ON p.id=m.product_id WHERE m.operation_id=NEW.operation_id AND (f.line_id IS NULL OR h.batch_id IS NULL OR b.id IS NULL OR bs.batch_id IS NULL OR a.product_id IS NULL OR p.id IS NULL OR f.product_id<>m.product_id OR f.branch_id<>m.branch_id OR f.batch_key<>b.batch_key OR CAST(f.quantity_after AS REAL)<>CAST(f.quantity_before AS REAL)+m.quantity OR CAST(f.received_after AS REAL)<>CAST(f.received_before AS REAL)+m.quantity OR f.gross_after4-f.gross_before4<>(SELECT gross4 FROM stock_epoch_sources WHERE movement_id=m.movement_id) OR f.branch_after<>f.branch_before+m.quantity OR f.product_after<>f.product_before+m.quantity OR h.operation_id<>NEW.operation_id OR h.quantity<>f.quantity_after OR h.received_quantity<>f.received_after OR h.received_gross4<>f.gross_after4 OR bs.quantity<>CAST(f.quantity_after AS REAL) OR b.received_quantity<>CAST(f.received_after AS REAL) OR b.received_cost_usd<>f.gross_after4/10000.0 OR a.quantity<>f.branch_after OR p.stock_quantity<>f.product_after)) THEN 1 ELSE RAISE(ABORT,'epoch physical publication incomplete') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM system_flags WHERE key='maintenance') THEN 1 ELSE RAISE(ABORT,'epoch maintenance active') END;
END;

CREATE TRIGGER stock_epoch_protocol2_scope BEFORE INSERT ON stock_epoch_operations WHEN NEW.protocol=2 AND (NEW.kind NOT IN ('stock_session','hold','repair') OR NEW.epoch_count<>0 OR NEW.assignment_count<>0 OR NEW.source_count>25 OR (NEW.kind<>'stock_session' AND NEW.source_count<>1) OR (NEW.kind='stock_session' AND EXISTS(SELECT 1 FROM json_each(NEW.request_json,'$.items') j WHERE json_extract(j.value,'$.kind')<>'receive'))) BEGIN SELECT RAISE(ABORT,'epoch transition not implemented'); END;
CREATE TRIGGER stock_epoch_protocol2_event_scope BEFORE INSERT ON stock_epoch_events WHEN EXISTS(SELECT 1 FROM stock_epoch_operations WHERE id=NEW.operation_id AND protocol=2) AND (NEW.kind NOT IN ('admit','hold','repair') OR (NEW.kind='admit' AND (NEW.revision<>0 OR NEW.funding_generation<>0)) OR NEW.loss4<>0 OR NEW.recovery4<>0 OR NEW.consumed_cost4<>0 OR NEW.consumed_recovery4<>0) BEGIN SELECT RAISE(ABORT,'epoch transition not implemented'); END;
CREATE TRIGGER stock_epoch_protocol2_source_closed BEFORE INSERT ON stock_epoch_sources WHEN EXISTS(SELECT 1 FROM stock_epoch_publications WHERE operation_id=NEW.admission_operation_id) BEGIN SELECT RAISE(ABORT,'epoch publication closed'); END;
CREATE TRIGGER stock_epoch_protocol2_source_quantity BEFORE INSERT ON stock_epoch_sources WHEN EXISTS(SELECT 1 FROM stock_epoch_operations WHERE id=NEW.admission_operation_id AND protocol=2) AND (json_valid(NEW.quantity)=0 OR json_type(NEW.quantity) NOT IN ('integer','real') OR json_extract(NEW.quantity,'$')<=0 OR json_extract(NEW.quantity,'$')>1000000000 OR NEW.free_quantity<>'0') BEGIN SELECT RAISE(ABORT,'epoch receipt quantity invalid'); END;
CREATE TRIGGER stock_epoch_protocol2_history BEFORE INSERT ON stock_epoch_publications WHEN EXISTS(SELECT 1 FROM stock_epoch_operations WHERE id=NEW.operation_id AND protocol=2 AND kind='stock_session') AND NOT EXISTS(SELECT 1 FROM stock_epoch_operations e JOIN stock_session_operations s ON s.id=e.ordinary_id JOIN action_history h ON h.id=s.history_id JOIN undo_snapshots u ON u.id=s.snapshot_id WHERE e.id=NEW.operation_id AND h.entity='stock_session' AND h.entity_id=s.id AND h.status='undoable' AND h.created_by_id=s.actor_id AND json_extract(h.undo_payload,'$.operation_id')=s.id AND json_extract(h.undo_payload,'$.snapshot_id')=s.snapshot_id AND json_extract(h.redo_payload,'$.operation_id')=s.id AND json_extract(h.redo_payload,'$.snapshot_id')=s.snapshot_id AND u.created_by_id=s.actor_id AND json_extract(u.payload_json,'$.operationId')=s.id AND json_extract(u.payload_json,'$.version')=2 AND json_type(u.payload_json,'$.after')='object' AND json_extract(u.payload_json,'$.after')=json_extract(u.payload_json,'$.expected') AND json_extract(s.receipt_json,'$.actionHistoryId')=s.history_id AND json_extract(s.receipt_json,'$.snapshotId')=s.snapshot_id) BEGIN SELECT RAISE(ABORT,'epoch receipt history incomplete'); END;

DROP TRIGGER stock_epoch_publish_source_admission;
CREATE TRIGGER stock_epoch_publish_source_admission BEFORE INSERT ON stock_epoch_publications WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_operations WHERE id=NEW.operation_id AND protocol=2) AND EXISTS(SELECT 1 FROM stock_epoch_sources s JOIN product_batches b ON b.id=s.batch_id WHERE s.admission_operation_id=NEW.operation_id AND (NOT EXISTS(SELECT 1 FROM stock_epoch_events e WHERE e.operation_id=NEW.operation_id AND e.source_id=s.id AND e.kind='admit' AND e.revision=0) OR b.received_quantity<>(SELECT SUM(CAST(quantity AS REAL)) FROM stock_epoch_sources WHERE batch_id=s.batch_id) OR b.received_cost_usd<>(SELECT SUM(gross4)/10000.0 FROM stock_epoch_sources WHERE batch_id=s.batch_id) OR EXISTS(SELECT 1 FROM inventory_movements m WHERE m.batch_id=s.batch_id AND m.movement_type IN ('add','in') AND NOT EXISTS(SELECT 1 FROM stock_epoch_sources x WHERE x.movement_id=m.id)))) BEGIN SELECT RAISE(ABORT,'epoch source admission incomplete'); END;

CREATE TABLE stock_epoch_fragment_inputs(event_id TEXT NOT NULL REFERENCES stock_epoch_events(id),source_id TEXT NOT NULL REFERENCES stock_epoch_sources(id),before_event_id TEXT NOT NULL,before_segment_id TEXT NOT NULL,PRIMARY KEY(event_id,source_id,before_event_id,before_segment_id),UNIQUE(event_id,source_id,before_segment_id),FOREIGN KEY(before_event_id,before_segment_id) REFERENCES stock_epoch_segments(event_id,segment_id));

CREATE TABLE stock_epoch_commands(operation_id TEXT PRIMARY KEY REFERENCES stock_epoch_operations(id),source_id TEXT NOT NULL REFERENCES stock_epoch_sources(id),before_event_id TEXT NOT NULL REFERENCES stock_epoch_source_states(event_id),previous_lot_operation_id TEXT NOT NULL REFERENCES stock_epoch_operations(id),batch_id INTEGER NOT NULL REFERENCES product_batches(id),branch_id INTEGER NOT NULL REFERENCES branches(id),product_id INTEGER NOT NULL REFERENCES products(id),quantity_before TEXT NOT NULL,quantity_after TEXT NOT NULL CHECK(quantity_after>=0),branch_before TEXT NOT NULL,branch_after TEXT NOT NULL CHECK(branch_after>=0),product_before TEXT NOT NULL,product_after TEXT NOT NULL CHECK(product_after>=0),delta_quantity REAL NOT NULL,request_digest TEXT NOT NULL,response_json TEXT NOT NULL CHECK(json_valid(response_json)),movement_id INTEGER UNIQUE REFERENCES inventory_movements(id),audit_id INTEGER UNIQUE REFERENCES audit_logs(id));

CREATE INDEX stock_epoch_source_fragment_identity ON stock_epoch_segments(source_id,segment_id,event_id);

CREATE TRIGGER stock_epoch_input_owned BEFORE INSERT ON stock_epoch_fragment_inputs WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_events e JOIN stock_epoch_operations o ON o.id=e.operation_id JOIN stock_epoch_current_fragments h ON h.source_id=e.source_id JOIN stock_epoch_segments s ON s.event_id=h.event_id AND s.segment_id=h.segment_id WHERE e.id=NEW.event_id AND e.source_id=NEW.source_id AND h.event_id=NEW.before_event_id AND h.segment_id=NEW.before_segment_id AND s.source_id=NEW.source_id AND o.protocol=2 AND o.kind IN ('hold','repair') AND NOT EXISTS(SELECT 1 FROM stock_epoch_publications p WHERE p.operation_id=o.id)) BEGIN SELECT RAISE(ABORT,'epoch fragment preimage'); END;

CREATE TRIGGER stock_epoch_command_preimage BEFORE INSERT ON stock_epoch_commands WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_operations o JOIN stock_epoch_events e ON e.operation_id=o.id JOIN stock_epoch_source_heads h ON h.source_id=e.source_id JOIN stock_epoch_sources s ON s.id=h.source_id JOIN stock_epoch_lot_heads l ON l.batch_id=s.batch_id AND l.branch_id=s.branch_id JOIN branch_batch_stock b ON b.batch_id=l.batch_id AND b.branch_id=l.branch_id JOIN branch_stock a ON a.product_id=s.product_id AND a.branch_id=s.branch_id JOIN products p ON p.id=s.product_id WHERE o.id=NEW.operation_id AND o.protocol=2 AND o.kind IN ('hold','repair') AND h.event_id=NEW.before_event_id AND h.source_id=NEW.source_id AND l.operation_id=NEW.previous_lot_operation_id AND s.batch_id=NEW.batch_id AND s.branch_id=NEW.branch_id AND s.product_id=NEW.product_id AND b.quantity=NEW.quantity_before AND a.quantity=NEW.branch_before AND p.stock_quantity=NEW.product_before AND CAST(l.quantity AS REAL)=NEW.quantity_before AND e.revision=h.revision+1 AND e.funding_generation=h.funding_generation AND o.dataset_generation=h.dataset_generation AND json_extract(o.request_json,'$.source_id')=NEW.source_id AND json_extract(o.request_json,'$.expected_revision')=h.revision AND json_extract(o.request_json,'$.expected_generation')=h.funding_generation AND NOT EXISTS(SELECT 1 FROM stock_epoch_publications x WHERE x.operation_id=o.id)) BEGIN SELECT RAISE(ABORT,'epoch command preimage'); END;

DROP TRIGGER stock_epoch_source_heads_no_update;
CREATE TRIGGER stock_epoch_source_heads_no_update BEFORE UPDATE ON stock_epoch_source_heads WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_events e JOIN stock_epoch_operations o ON o.id=e.operation_id JOIN stock_epoch_commands c ON c.operation_id=o.id JOIN stock_epoch_source_states v ON v.event_id=e.id WHERE e.id=NEW.event_id AND e.source_id=OLD.source_id AND NEW.source_id=OLD.source_id AND c.source_id=OLD.source_id AND c.before_event_id=OLD.event_id AND NEW.revision=OLD.revision+1 AND e.revision=NEW.revision AND NEW.funding_generation=OLD.funding_generation AND v.funding_generation=NEW.funding_generation AND NEW.dataset_generation=OLD.dataset_generation AND o.dataset_generation=NEW.dataset_generation AND o.protocol=2 AND o.kind IN ('hold','repair') AND NOT EXISTS(SELECT 1 FROM stock_epoch_publications p WHERE p.operation_id=o.id)) BEGIN SELECT RAISE(ABORT,'epoch source head unowned'); END;

DROP TRIGGER stock_epoch_current_fragments_no_delete;
CREATE TRIGGER stock_epoch_current_fragments_no_delete BEFORE DELETE ON stock_epoch_current_fragments WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_fragment_inputs i JOIN stock_epoch_events e ON e.id=i.event_id JOIN stock_epoch_operations o ON o.id=e.operation_id JOIN stock_epoch_segments s ON s.event_id=e.id AND s.segment_id=i.before_segment_id WHERE i.source_id=OLD.source_id AND i.before_event_id=OLD.event_id AND i.before_segment_id=OLD.segment_id AND s.fate='retired' AND s.quantity='0' AND s.gross4=0 AND s.coverage4=0 AND o.protocol=2 AND o.kind IN ('hold','repair') AND NOT EXISTS(SELECT 1 FROM stock_epoch_publications p WHERE p.operation_id=o.id)) BEGIN SELECT RAISE(ABORT,'epoch fragment retirement unowned'); END;

DROP TRIGGER stock_epoch_member_preimage;
CREATE TRIGGER stock_epoch_member_preimage BEFORE INSERT ON stock_epoch_operation_sources WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_operations WHERE id=NEW.operation_id AND protocol=2) AND (NEW.expected_revision<>(SELECT COALESCE(MAX(revision),-1) FROM stock_epoch_event_registry WHERE source_id=NEW.source_id) OR NEW.expected_funding_generation<>COALESCE((SELECT funding_generation FROM stock_epoch_events WHERE source_id=NEW.source_id ORDER BY revision DESC LIMIT 1),(SELECT MAX(generation) FROM stock_funding_events WHERE source_id=NEW.source_id),-1) ) BEGIN SELECT RAISE(ABORT,'epoch source changed'); END;

CREATE TRIGGER stock_epoch_typed_member_preimage BEFORE INSERT ON stock_epoch_operation_sources WHEN EXISTS(SELECT 1 FROM stock_epoch_operations WHERE id=NEW.operation_id AND protocol=2) AND NOT ((NEW.expected_revision=-1 AND NEW.expected_funding_generation=-1 AND NOT EXISTS(SELECT 1 FROM stock_epoch_event_registry WHERE source_id=NEW.source_id)) OR EXISTS(SELECT 1 FROM stock_epoch_source_heads h JOIN stock_epoch_events e ON e.id=h.event_id JOIN stock_epoch_publications p ON p.operation_id=e.operation_id WHERE h.source_id=NEW.source_id AND h.revision=NEW.expected_revision AND h.funding_generation=NEW.expected_funding_generation AND h.dataset_generation=(SELECT generation FROM stock_epoch_dataset WHERE singleton=1))) BEGIN SELECT RAISE(ABORT,'epoch source changed'); END;

CREATE TRIGGER stock_epoch_fragment_inputs_closed_insert BEFORE INSERT ON stock_epoch_fragment_inputs WHEN EXISTS(SELECT 1 FROM stock_epoch_publications WHERE operation_id=(SELECT operation_id FROM stock_epoch_events WHERE id=NEW.event_id)) BEGIN SELECT RAISE(ABORT,'epoch publication closed'); END;

CREATE TRIGGER stock_epoch_fragment_inputs_no_delete BEFORE DELETE ON stock_epoch_fragment_inputs BEGIN SELECT RAISE(ABORT,'epoch immutable'); END;

CREATE TRIGGER stock_epoch_commands_closed_insert BEFORE INSERT ON stock_epoch_commands WHEN EXISTS(SELECT 1 FROM stock_epoch_publications WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'epoch publication closed'); END;

CREATE TRIGGER stock_epoch_commands_no_delete BEFORE DELETE ON stock_epoch_commands BEGIN SELECT RAISE(ABORT,'epoch immutable'); END;

CREATE TRIGGER stock_epoch_fragment_inputs_no_update BEFORE UPDATE ON stock_epoch_fragment_inputs BEGIN SELECT RAISE(ABORT,'epoch immutable'); END;

CREATE TRIGGER stock_epoch_commands_no_update BEFORE UPDATE ON stock_epoch_commands WHEN NEW.operation_id IS NOT OLD.operation_id OR NEW.source_id IS NOT OLD.source_id OR NEW.before_event_id IS NOT OLD.before_event_id OR NEW.previous_lot_operation_id IS NOT OLD.previous_lot_operation_id OR NEW.batch_id IS NOT OLD.batch_id OR NEW.branch_id IS NOT OLD.branch_id OR NEW.product_id IS NOT OLD.product_id OR NEW.quantity_before IS NOT OLD.quantity_before OR NEW.quantity_after IS NOT OLD.quantity_after OR NEW.branch_before IS NOT OLD.branch_before OR NEW.branch_after IS NOT OLD.branch_after OR NEW.product_before IS NOT OLD.product_before OR NEW.product_after IS NOT OLD.product_after OR NEW.delta_quantity IS NOT OLD.delta_quantity OR NEW.request_digest IS NOT OLD.request_digest OR NEW.response_json IS NOT OLD.response_json OR (OLD.movement_id IS NOT NULL AND NEW.movement_id IS NOT OLD.movement_id) OR (OLD.audit_id IS NOT NULL AND NEW.audit_id IS NOT OLD.audit_id) OR EXISTS(SELECT 1 FROM stock_epoch_publications WHERE operation_id=OLD.operation_id) BEGIN SELECT RAISE(ABORT,'epoch command immutable'); END;

CREATE TRIGGER stock_epoch_quantity_shape BEFORE INSERT ON stock_epoch_segments WHEN NEW.source_id IS NOT NULL AND (json_valid(NEW.quantity)=0 OR json_type(NEW.quantity) NOT IN ('integer','real') OR NEW.quantity GLOB '*[^0-9.]*' OR length(NEW.quantity)-length(replace(NEW.quantity,'.',''))>1 OR (instr(NEW.quantity,'.')>0 AND length(NEW.quantity)-instr(NEW.quantity,'.')>24) OR CAST(NEW.quantity AS REAL)<0 OR CAST(NEW.quantity AS REAL)>1000000000 OR (CAST(NEW.quantity AS REAL)=0 AND (NEW.gross4<>0 OR NEW.coverage4<>0))) BEGIN SELECT RAISE(ABORT,'epoch fragment quantity'); END;

CREATE VIEW stock_epoch_quantity_terms AS
SELECT i.event_id,'partition:'||i.before_segment_id AS group_key,0 AS side,g.quantity FROM stock_epoch_fragment_inputs i JOIN stock_epoch_segments g ON g.event_id=i.before_event_id AND g.segment_id=i.before_segment_id
UNION ALL SELECT i.event_id,'partition:'||i.before_segment_id,1,g.quantity FROM stock_epoch_fragment_inputs i JOIN stock_epoch_segments g ON g.event_id=i.event_id AND g.parent_segment_id=i.before_segment_id AND g.fate<>'retired'
UNION ALL SELECT e.id,'fate:sellable',0,v.sellable_quantity FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states v ON v.event_id=e.id
UNION ALL SELECT i.event_id,'fate:sellable',0,g.quantity FROM stock_epoch_fragment_inputs i JOIN stock_epoch_segments g ON g.event_id=i.before_event_id AND g.segment_id=i.before_segment_id WHERE g.fate='sellable'
UNION ALL SELECT e.id,'fate:sellable',1,v.sellable_quantity FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states v ON v.event_id=c.before_event_id
UNION ALL SELECT e.id,'fate:sellable',1,g.quantity FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_segments g ON g.event_id=e.id WHERE g.fate='sellable'
UNION ALL SELECT e.id,'fate:held',0,v.held_quantity FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states v ON v.event_id=e.id
UNION ALL SELECT i.event_id,'fate:held',0,g.quantity FROM stock_epoch_fragment_inputs i JOIN stock_epoch_segments g ON g.event_id=i.before_event_id AND g.segment_id=i.before_segment_id WHERE g.fate='held'
UNION ALL SELECT e.id,'fate:held',1,v.held_quantity FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states v ON v.event_id=c.before_event_id
UNION ALL SELECT e.id,'fate:held',1,g.quantity FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_segments g ON g.event_id=e.id WHERE g.fate='held'
UNION ALL SELECT e.id,'fate:disposed',0,v.disposed_quantity FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states v ON v.event_id=e.id
UNION ALL SELECT i.event_id,'fate:disposed',0,g.quantity FROM stock_epoch_fragment_inputs i JOIN stock_epoch_segments g ON g.event_id=i.before_event_id AND g.segment_id=i.before_segment_id WHERE g.fate='disposed'
UNION ALL SELECT e.id,'fate:disposed',1,v.disposed_quantity FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states v ON v.event_id=c.before_event_id
UNION ALL SELECT e.id,'fate:disposed',1,g.quantity FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_segments g ON g.event_id=e.id WHERE g.fate='disposed'
UNION ALL SELECT e.id,'fate:consumed',0,v.consumed_quantity FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states v ON v.event_id=e.id
UNION ALL SELECT i.event_id,'fate:consumed',0,g.quantity FROM stock_epoch_fragment_inputs i JOIN stock_epoch_segments g ON g.event_id=i.before_event_id AND g.segment_id=i.before_segment_id WHERE g.fate='consumed'
UNION ALL SELECT e.id,'fate:consumed',1,v.consumed_quantity FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states v ON v.event_id=c.before_event_id
UNION ALL SELECT e.id,'fate:consumed',1,g.quantity FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_segments g ON g.event_id=e.id WHERE g.fate='consumed'
UNION ALL SELECT e.id,'physical:lot',0,c.quantity_after FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id
UNION ALL SELECT e.id,'physical:lot',1,c.quantity_before FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id
UNION ALL SELECT e.id,'physical:lot',CASE WHEN e.kind='hold' THEN 0 ELSE 1 END,g.quantity FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_operations o ON o.id=e.operation_id JOIN stock_epoch_segments g ON g.event_id=e.id AND g.segment_id=json_extract(o.request_json,'$.child_segment_id')
UNION ALL SELECT e.id,'physical:branch',0,c.branch_after FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id
UNION ALL SELECT e.id,'physical:branch',1,c.branch_before FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id
UNION ALL SELECT e.id,'physical:branch',CASE WHEN e.kind='hold' THEN 0 ELSE 1 END,g.quantity FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_operations o ON o.id=e.operation_id JOIN stock_epoch_segments g ON g.event_id=e.id AND g.segment_id=json_extract(o.request_json,'$.child_segment_id')
UNION ALL SELECT e.id,'physical:product',0,c.product_after FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id
UNION ALL SELECT e.id,'physical:product',1,c.product_before FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id
UNION ALL SELECT e.id,'physical:product',CASE WHEN e.kind='hold' THEN 0 ELSE 1 END,g.quantity FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_operations o ON o.id=e.operation_id JOIN stock_epoch_segments g ON g.event_id=e.id AND g.segment_id=json_extract(o.request_json,'$.child_segment_id');

CREATE VIEW stock_epoch_quantity_parts AS SELECT event_id,group_key,side,CAST(quantity AS INTEGER) AS whole,CAST(substr(CASE WHEN instr(quantity,'.')>0 THEN substr(quantity,instr(quantity,'.')+1) ELSE '' END||'000000000000000000000000',1,6) AS INTEGER) AS p1,CAST(substr(CASE WHEN instr(quantity,'.')>0 THEN substr(quantity,instr(quantity,'.')+1) ELSE '' END||'000000000000000000000000',7,6) AS INTEGER) AS p2,CAST(substr(CASE WHEN instr(quantity,'.')>0 THEN substr(quantity,instr(quantity,'.')+1) ELSE '' END||'000000000000000000000000',13,6) AS INTEGER) AS p3,CAST(substr(CASE WHEN instr(quantity,'.')>0 THEN substr(quantity,instr(quantity,'.')+1) ELSE '' END||'000000000000000000000000',19,6) AS INTEGER) AS p4 FROM stock_epoch_quantity_terms;

CREATE VIEW stock_epoch_quantity_sums AS SELECT event_id,group_key,side,SUM(whole) AS whole,SUM(p1) AS p1,SUM(p2) AS p2,SUM(p3) AS p3,SUM(p4) AS p4 FROM stock_epoch_quantity_parts GROUP BY event_id,group_key,side;

CREATE VIEW stock_epoch_quantity_proofs AS SELECT event_id,group_key,side,json_array(whole+((p1+((p2+((p3+(p4/1000000))/1000000))/1000000))/1000000),(p1+((p2+((p3+(p4/1000000))/1000000))/1000000))%1000000,(p2+((p3+(p4/1000000))/1000000))%1000000,(p3+(p4/1000000))%1000000,p4%1000000) AS exact_quantity FROM stock_epoch_quantity_sums;

CREATE TRIGGER stock_epoch_publish_partition BEFORE INSERT ON stock_epoch_publications WHEN EXISTS(SELECT 1 FROM stock_epoch_operations WHERE id=NEW.operation_id AND protocol=2 AND kind IN ('hold','repair')) BEGIN
SELECT CASE WHEN EXISTS(SELECT 1 FROM stock_epoch_operations o JOIN users u ON u.id=o.actor_id LEFT JOIN roles r ON r.id=u.role_id JOIN stock_epoch_commands c ON c.operation_id=o.id JOIN stock_epoch_events e ON e.operation_id=o.id JOIN stock_epoch_source_states v ON v.event_id=e.id JOIN stock_epoch_source_heads h ON h.source_id=e.source_id JOIN stock_epoch_receipts receipt ON receipt.event_id=e.id JOIN audit_logs a ON a.id=c.audit_id WHERE o.id=NEW.operation_id AND o.kind=e.kind AND o.source_count=1 AND o.epoch_count=0 AND o.assignment_count=0 AND u.is_active=1 AND u.deleted_at IS NULL AND u.permissions IS o.actor_permissions AND u.role_id IS o.role_id AND r.code IS o.role_code AND r.permissions IS o.role_permissions AND h.event_id=e.id AND h.revision=e.revision AND h.funding_generation=e.funding_generation AND h.dataset_generation=o.dataset_generation AND o.dataset_generation=(SELECT generation FROM stock_epoch_dataset WHERE singleton=1) AND receipt.actor_id=o.actor_id AND receipt.request_id=o.request_id AND receipt.request_json=o.request_json AND receipt.request_digest=c.request_digest AND receipt.response_json=c.response_json AND a.user_id=o.actor_id AND a.entity='stock_epoch' AND a.entity_id=e.id AND a.action=e.kind AND a.details=c.response_json AND a.new_value=c.response_json AND json_extract(c.response_json,'$.source_id')=e.source_id AND json_extract(c.response_json,'$.event_id')=e.id AND json_extract(c.response_json,'$.revision')=e.revision AND json_extract(c.response_json,'$.kind')=e.kind) THEN 1 ELSE RAISE(ABORT,'epoch transition publication incomplete') END;
SELECT CASE WHEN (SELECT COUNT(*) FROM stock_epoch_fragment_inputs i JOIN stock_epoch_events e ON e.id=i.event_id WHERE e.operation_id=NEW.operation_id)=1 AND NOT EXISTS(SELECT 1 FROM stock_epoch_fragment_inputs i JOIN stock_epoch_events e ON e.id=i.event_id JOIN stock_epoch_operations o ON o.id=e.operation_id JOIN stock_epoch_segments b ON b.event_id=i.before_event_id AND b.segment_id=i.before_segment_id WHERE e.operation_id=NEW.operation_id AND (i.source_id<>e.source_id OR i.before_segment_id<>json_extract(o.request_json,'$.segment_id') OR b.fate<>CASE e.kind WHEN 'hold' THEN 'sellable' ELSE 'held' END OR EXISTS(SELECT 1 FROM stock_epoch_current_fragments h WHERE h.source_id=i.source_id AND h.segment_id=i.before_segment_id) OR NOT EXISTS(SELECT 1 FROM stock_epoch_segments g WHERE g.event_id=e.id AND g.segment_id=i.before_segment_id AND g.parent_segment_id=i.before_segment_id AND g.fate='retired' AND g.quantity='0' AND g.gross4=0 AND g.coverage4=0) OR b.gross4<>(SELECT SUM(gross4) FROM stock_epoch_segments g WHERE g.event_id=e.id AND g.parent_segment_id=i.before_segment_id AND g.fate<>'retired') OR b.coverage4<>(SELECT SUM(coverage4) FROM stock_epoch_segments g WHERE g.event_id=e.id AND g.parent_segment_id=i.before_segment_id AND g.fate<>'retired'))) THEN 1 ELSE RAISE(ABORT,'epoch split input incomplete') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_quantity_proofs left_side JOIN stock_epoch_events e ON e.id=left_side.event_id LEFT JOIN stock_epoch_quantity_proofs right_side ON right_side.event_id=left_side.event_id AND right_side.group_key=left_side.group_key AND right_side.side=1 WHERE e.operation_id=NEW.operation_id AND left_side.side=0 AND (right_side.event_id IS NULL OR left_side.exact_quantity<>right_side.exact_quantity)) THEN 1 ELSE RAISE(ABORT,'epoch exact quantity partition') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_segments g JOIN stock_epoch_events e ON e.id=g.event_id WHERE e.operation_id=NEW.operation_id AND (g.source_id<>e.source_id OR NOT EXISTS(SELECT 1 FROM stock_epoch_fragment_inputs i WHERE i.event_id=e.id AND i.source_id=e.source_id AND i.before_segment_id=g.parent_segment_id) OR g.loss4<>0 OR g.recovery4<>0 OR g.consumed_cost4<>0 OR g.consumed_recovery4<>0 OR g.consumption_id IS NOT NULL OR (g.fate<>'retired' AND NOT EXISTS(SELECT 1 FROM stock_epoch_current_fragments h WHERE h.source_id=e.source_id AND h.segment_id=g.segment_id AND h.event_id=e.id AND h.fate=g.fate AND h.allocation_id=g.allocation_id AND h.branch_id=g.branch_id)))) THEN 1 ELSE RAISE(ABORT,'epoch split output incomplete') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_operations o ON o.id=c.operation_id JOIN stock_epoch_segments g ON g.event_id=e.id AND g.segment_id=json_extract(o.request_json,'$.child_segment_id') JOIN inventory_movements m ON m.id=c.movement_id JOIN stock_epoch_lot_heads h ON h.batch_id=c.batch_id AND h.branch_id=c.branch_id JOIN branch_batch_stock b ON b.batch_id=c.batch_id AND b.branch_id=c.branch_id JOIN branch_stock a ON a.product_id=c.product_id AND a.branch_id=c.branch_id JOIN products p ON p.id=c.product_id WHERE c.operation_id=NEW.operation_id AND (g.fate<>CASE e.kind WHEN 'hold' THEN 'held' ELSE 'sellable' END OR CAST(g.quantity AS REAL)<>json_extract(o.request_json,'$.quantity') OR c.delta_quantity<>CAST(g.quantity AS REAL)*CASE e.kind WHEN 'hold' THEN -1 ELSE 1 END OR b.quantity<>CAST(c.quantity_after AS REAL) OR a.quantity<>CAST(c.branch_after AS REAL) OR p.stock_quantity<>CAST(c.product_after AS REAL) OR h.operation_id<>c.operation_id OR CAST(h.quantity AS REAL)<>CAST(c.quantity_after AS REAL) OR m.product_id<>c.product_id OR m.branch_id<>c.branch_id OR m.batch_id<>c.batch_id OR m.quantity<>c.delta_quantity OR m.reference_id<>c.operation_id OR m.user_id<>o.actor_id OR m.movement_type<>CASE e.kind WHEN 'hold' THEN 'remove' ELSE 'add' END)) AND EXISTS(SELECT 1 FROM stock_epoch_commands c JOIN inventory_movements m ON m.id=c.movement_id WHERE c.operation_id=NEW.operation_id) THEN 1 ELSE RAISE(ABORT,'epoch transition physical effects') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states old_state ON old_state.event_id=c.before_event_id JOIN stock_epoch_source_states next_state ON next_state.event_id=e.id WHERE c.operation_id=NEW.operation_id AND next_state.sellable_net4+COALESCE((SELECT SUM(g.gross4-g.coverage4) FROM stock_epoch_fragment_inputs i JOIN stock_epoch_segments g ON g.event_id=i.before_event_id AND g.segment_id=i.before_segment_id WHERE i.event_id=e.id AND g.fate='sellable'),0)<>old_state.sellable_net4+COALESCE((SELECT SUM(gross4-coverage4) FROM stock_epoch_segments WHERE event_id=e.id AND fate='sellable'),0)) THEN 1 ELSE RAISE(ABORT,'epoch sellable_net4 transition') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states old_state ON old_state.event_id=c.before_event_id JOIN stock_epoch_source_states next_state ON next_state.event_id=e.id WHERE c.operation_id=NEW.operation_id AND next_state.held_net4+COALESCE((SELECT SUM(g.gross4-g.coverage4) FROM stock_epoch_fragment_inputs i JOIN stock_epoch_segments g ON g.event_id=i.before_event_id AND g.segment_id=i.before_segment_id WHERE i.event_id=e.id AND g.fate='held'),0)<>old_state.held_net4+COALESCE((SELECT SUM(gross4-coverage4) FROM stock_epoch_segments WHERE event_id=e.id AND fate='held'),0)) THEN 1 ELSE RAISE(ABORT,'epoch held_net4 transition') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states old_state ON old_state.event_id=c.before_event_id JOIN stock_epoch_source_states next_state ON next_state.event_id=e.id WHERE c.operation_id=NEW.operation_id AND next_state.loss4+COALESCE((SELECT SUM(g.loss4) FROM stock_epoch_fragment_inputs i JOIN stock_epoch_segments g ON g.event_id=i.before_event_id AND g.segment_id=i.before_segment_id WHERE i.event_id=e.id AND g.fate='disposed'),0)<>old_state.loss4+COALESCE((SELECT SUM(loss4) FROM stock_epoch_segments WHERE event_id=e.id AND fate='disposed'),0)) THEN 1 ELSE RAISE(ABORT,'epoch loss4 transition') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states old_state ON old_state.event_id=c.before_event_id JOIN stock_epoch_source_states next_state ON next_state.event_id=e.id WHERE c.operation_id=NEW.operation_id AND next_state.loss_recovery4+COALESCE((SELECT SUM(g.recovery4) FROM stock_epoch_fragment_inputs i JOIN stock_epoch_segments g ON g.event_id=i.before_event_id AND g.segment_id=i.before_segment_id WHERE i.event_id=e.id AND g.fate='disposed'),0)<>old_state.loss_recovery4+COALESCE((SELECT SUM(recovery4) FROM stock_epoch_segments WHERE event_id=e.id AND fate='disposed'),0)) THEN 1 ELSE RAISE(ABORT,'epoch loss_recovery4 transition') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states old_state ON old_state.event_id=c.before_event_id JOIN stock_epoch_source_states next_state ON next_state.event_id=e.id WHERE c.operation_id=NEW.operation_id AND next_state.consumed_cost4+COALESCE((SELECT SUM(g.consumed_cost4) FROM stock_epoch_fragment_inputs i JOIN stock_epoch_segments g ON g.event_id=i.before_event_id AND g.segment_id=i.before_segment_id WHERE i.event_id=e.id AND g.fate='consumed'),0)<>old_state.consumed_cost4+COALESCE((SELECT SUM(consumed_cost4) FROM stock_epoch_segments WHERE event_id=e.id AND fate='consumed'),0)) THEN 1 ELSE RAISE(ABORT,'epoch consumed_cost4 transition') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states old_state ON old_state.event_id=c.before_event_id JOIN stock_epoch_source_states next_state ON next_state.event_id=e.id WHERE c.operation_id=NEW.operation_id AND next_state.consumed_recovery4+COALESCE((SELECT SUM(g.consumed_recovery4) FROM stock_epoch_fragment_inputs i JOIN stock_epoch_segments g ON g.event_id=i.before_event_id AND g.segment_id=i.before_segment_id WHERE i.event_id=e.id AND g.fate='consumed'),0)<>old_state.consumed_recovery4+COALESCE((SELECT SUM(consumed_recovery4) FROM stock_epoch_segments WHERE event_id=e.id AND fate='consumed'),0)) THEN 1 ELSE RAISE(ABORT,'epoch consumed_recovery4 transition') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM system_flags WHERE key='maintenance') THEN 1 ELSE RAISE(ABORT,'epoch maintenance active') END;
END;

CREATE TRIGGER stock_epoch_state_quantity_shape BEFORE INSERT ON stock_epoch_source_states WHEN (json_valid(NEW.sellable_quantity)=0 OR json_type(NEW.sellable_quantity) NOT IN ('integer','real') OR NEW.sellable_quantity GLOB '*[^0-9.]*' OR (instr(NEW.sellable_quantity,'.')>0 AND length(NEW.sellable_quantity)-instr(NEW.sellable_quantity,'.')>24) OR CAST(NEW.sellable_quantity AS REAL)<0 OR CAST(NEW.sellable_quantity AS REAL)>1000000000) OR (json_valid(NEW.held_quantity)=0 OR json_type(NEW.held_quantity) NOT IN ('integer','real') OR NEW.held_quantity GLOB '*[^0-9.]*' OR (instr(NEW.held_quantity,'.')>0 AND length(NEW.held_quantity)-instr(NEW.held_quantity,'.')>24) OR CAST(NEW.held_quantity AS REAL)<0 OR CAST(NEW.held_quantity AS REAL)>1000000000) OR (json_valid(NEW.disposed_quantity)=0 OR json_type(NEW.disposed_quantity) NOT IN ('integer','real') OR NEW.disposed_quantity GLOB '*[^0-9.]*' OR (instr(NEW.disposed_quantity,'.')>0 AND length(NEW.disposed_quantity)-instr(NEW.disposed_quantity,'.')>24) OR CAST(NEW.disposed_quantity AS REAL)<0 OR CAST(NEW.disposed_quantity AS REAL)>1000000000) OR (json_valid(NEW.consumed_quantity)=0 OR json_type(NEW.consumed_quantity) NOT IN ('integer','real') OR NEW.consumed_quantity GLOB '*[^0-9.]*' OR (instr(NEW.consumed_quantity,'.')>0 AND length(NEW.consumed_quantity)-instr(NEW.consumed_quantity,'.')>24) OR CAST(NEW.consumed_quantity AS REAL)<0 OR CAST(NEW.consumed_quantity AS REAL)>1000000000) BEGIN SELECT RAISE(ABORT,'epoch state quantity'); END;
CREATE TRIGGER stock_epoch_fragment_inputs_no_replace BEFORE INSERT ON stock_epoch_fragment_inputs WHEN EXISTS(SELECT 1 FROM stock_epoch_fragment_inputs WHERE event_id=NEW.event_id AND source_id=NEW.source_id AND before_segment_id=NEW.before_segment_id) BEGIN SELECT RAISE(ABORT,'epoch immutable identity'); END;
CREATE TRIGGER stock_epoch_commands_no_replace BEFORE INSERT ON stock_epoch_commands WHEN EXISTS(SELECT 1 FROM stock_epoch_commands WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'epoch immutable identity'); END;

CREATE TRIGGER stock_epoch_partition_output_shape BEFORE INSERT ON stock_epoch_publications WHEN EXISTS(SELECT 1 FROM stock_epoch_operations WHERE id=NEW.operation_id AND protocol=2 AND kind IN ('hold','repair')) BEGIN
SELECT CASE WHEN EXISTS(SELECT 1 FROM stock_epoch_operations o JOIN stock_epoch_events e ON e.operation_id=o.id JOIN stock_epoch_commands c ON c.operation_id=o.id JOIN stock_epoch_sources source ON source.id=c.source_id JOIN stock_epoch_fragment_inputs i ON i.event_id=e.id JOIN stock_epoch_segments before_leaf ON before_leaf.event_id=i.before_event_id AND before_leaf.segment_id=i.before_segment_id JOIN stock_epoch_segments child ON child.event_id=e.id AND child.segment_id=json_extract(o.request_json,'$.child_segment_id') JOIN stock_epoch_lot_heads h ON h.batch_id=c.batch_id AND h.branch_id=c.branch_id JOIN branch_batch_stock b ON b.batch_id=c.batch_id AND b.branch_id=c.branch_id JOIN branch_stock a ON a.product_id=c.product_id AND a.branch_id=c.branch_id JOIN products p ON p.id=c.product_id JOIN inventory_movements m ON m.id=c.movement_id WHERE o.id=NEW.operation_id AND child.parent_segment_id=i.before_segment_id AND child.source_id=c.source_id AND child.branch_id=source.branch_id AND child.fate=CASE e.kind WHEN 'hold' THEN 'held' ELSE 'sellable' END AND child.allocation_id=CASE WHEN e.kind='hold' AND before_leaf.allocation_id='origin' THEN child.segment_id ELSE before_leaf.allocation_id END AND child.reason=CASE e.kind WHEN 'hold' THEN json_extract(o.request_json,'$.reason') ELSE '' END AND child.segment_id<>i.before_segment_id AND child.segment_id||'-remaining'<>i.before_segment_id) THEN 1 ELSE RAISE(ABORT,'epoch required partition child') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_operations o JOIN stock_epoch_events e ON e.operation_id=o.id JOIN stock_epoch_fragment_inputs i ON i.event_id=e.id JOIN stock_epoch_segments before_leaf ON before_leaf.event_id=i.before_event_id AND before_leaf.segment_id=i.before_segment_id JOIN stock_epoch_segments g ON g.event_id=e.id WHERE o.id=NEW.operation_id AND ((g.fate='retired' AND g.segment_id<>i.before_segment_id) OR (g.fate<>'retired' AND CAST(g.quantity AS REAL)<=0) OR (g.fate<>'retired' AND g.segment_id NOT IN (json_extract(o.request_json,'$.child_segment_id'),json_extract(o.request_json,'$.child_segment_id')||'-remaining')) OR (g.segment_id=json_extract(o.request_json,'$.child_segment_id')||'-remaining' AND (g.fate<>before_leaf.fate OR g.allocation_id<>before_leaf.allocation_id OR g.reason<>before_leaf.reason OR g.branch_id<>before_leaf.branch_id)))) THEN 1 ELSE RAISE(ABORT,'epoch unauthorized partition child') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states s ON s.event_id=e.id WHERE c.operation_id=NEW.operation_id AND (json_extract(c.response_json,'$.totals.event_id') IS NOT s.event_id OR json_extract(c.response_json,'$.totals.source_id') IS NOT s.source_id OR json_extract(c.response_json,'$.totals.funding_generation') IS NOT s.funding_generation OR json_extract(c.response_json,'$.totals.gross4') IS NOT s.gross4 OR json_extract(c.response_json,'$.totals.paid4') IS NOT s.paid4 OR json_extract(c.response_json,'$.totals.debt4') IS NOT s.debt4 OR json_extract(c.response_json,'$.totals.credit4') IS NOT s.credit4)) THEN 1 ELSE RAISE(ABORT,'epoch typed receipt mismatch') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states s ON s.event_id=e.id WHERE c.operation_id=NEW.operation_id AND (json_extract(c.response_json,'$.totals.asset4') IS NOT s.asset4 OR json_extract(c.response_json,'$.totals.cash_in4') IS NOT s.cash_in4 OR json_extract(c.response_json,'$.totals.cash_out4') IS NOT s.cash_out4 OR json_extract(c.response_json,'$.totals.shipping4') IS NOT s.shipping4 OR json_extract(c.response_json,'$.totals.sellable_quantity') IS NOT s.sellable_quantity OR json_extract(c.response_json,'$.totals.held_quantity') IS NOT s.held_quantity OR json_extract(c.response_json,'$.totals.disposed_quantity') IS NOT s.disposed_quantity)) THEN 1 ELSE RAISE(ABORT,'epoch typed receipt mismatch') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states s ON s.event_id=e.id WHERE c.operation_id=NEW.operation_id AND (json_extract(c.response_json,'$.totals.consumed_quantity') IS NOT s.consumed_quantity OR json_extract(c.response_json,'$.totals.sellable_net4') IS NOT s.sellable_net4 OR json_extract(c.response_json,'$.totals.held_net4') IS NOT s.held_net4 OR json_extract(c.response_json,'$.totals.loss4') IS NOT s.loss4 OR json_extract(c.response_json,'$.totals.loss_recovery4') IS NOT s.loss_recovery4 OR json_extract(c.response_json,'$.totals.consumed_cost4') IS NOT s.consumed_cost4 OR json_extract(c.response_json,'$.totals.consumed_recovery4') IS NOT s.consumed_recovery4)) THEN 1 ELSE RAISE(ABORT,'epoch typed receipt mismatch') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN stock_epoch_source_states s ON s.event_id=e.id WHERE c.operation_id=NEW.operation_id AND (json_extract(c.response_json,'$.totals.pending4') IS NOT s.pending4)) THEN 1 ELSE RAISE(ABORT,'epoch typed receipt mismatch') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id WHERE c.operation_id=NEW.operation_id AND (json_array_length(c.response_json,'$.changed_segments')<>(SELECT COUNT(*) FROM stock_epoch_segments g WHERE g.event_id=e.id AND g.fate<>'retired') OR EXISTS(SELECT 1 FROM stock_epoch_segments g WHERE g.event_id=e.id AND g.fate<>'retired' AND NOT EXISTS(SELECT 1 FROM json_each(c.response_json,'$.changed_segments') j WHERE json_extract(j.value,'$.event_id') IS g.event_id AND json_extract(j.value,'$.segment_id') IS g.segment_id AND json_extract(j.value,'$.allocation_id') IS g.allocation_id AND json_extract(j.value,'$.fate') IS g.fate AND json_extract(j.value,'$.quantity') IS g.quantity AND json_extract(j.value,'$.gross4') IS g.gross4 AND json_extract(j.value,'$.coverage4') IS g.coverage4 AND json_extract(j.value,'$.loss4') IS g.loss4 AND json_extract(j.value,'$.recovery4') IS g.recovery4 AND json_extract(j.value,'$.reason') IS g.reason AND json_extract(j.value,'$.consumption_id') IS g.consumption_id AND json_extract(j.value,'$.consumed_cost4') IS g.consumed_cost4 AND json_extract(j.value,'$.consumed_recovery4') IS g.consumed_recovery4 AND json_extract(j.value,'$.source_id') IS g.source_id AND json_extract(j.value,'$.branch_id') IS g.branch_id AND json_extract(j.value,'$.parent_segment_id') IS g.parent_segment_id)))) THEN 1 ELSE RAISE(ABORT,'epoch changed fragment receipt mismatch') END;
SELECT CASE WHEN (SELECT COUNT(*) FROM stock_epoch_commands c JOIN stock_epoch_events e ON e.operation_id=c.operation_id JOIN audit_logs a ON a.entity='stock_epoch' AND a.entity_id=e.id WHERE c.operation_id=NEW.operation_id)=1 THEN 1 ELSE RAISE(ABORT,'epoch transition audit membership') END;
END;

CREATE TRIGGER stock_epoch_command_quantity_shape BEFORE INSERT ON stock_epoch_commands WHEN (json_valid(NEW.quantity_before)=0 OR json_type(NEW.quantity_before) NOT IN ('integer','real') OR NEW.quantity_before GLOB '*[^0-9.]*' OR (instr(NEW.quantity_before,'.')>0 AND length(NEW.quantity_before)-instr(NEW.quantity_before,'.')>24) OR CAST(NEW.quantity_before AS REAL)<0 OR CAST(NEW.quantity_before AS REAL)>1000000000) OR (json_valid(NEW.quantity_after)=0 OR json_type(NEW.quantity_after) NOT IN ('integer','real') OR NEW.quantity_after GLOB '*[^0-9.]*' OR (instr(NEW.quantity_after,'.')>0 AND length(NEW.quantity_after)-instr(NEW.quantity_after,'.')>24) OR CAST(NEW.quantity_after AS REAL)<0 OR CAST(NEW.quantity_after AS REAL)>1000000000) OR (json_valid(NEW.branch_before)=0 OR json_type(NEW.branch_before) NOT IN ('integer','real') OR NEW.branch_before GLOB '*[^0-9.]*' OR (instr(NEW.branch_before,'.')>0 AND length(NEW.branch_before)-instr(NEW.branch_before,'.')>24) OR CAST(NEW.branch_before AS REAL)<0 OR CAST(NEW.branch_before AS REAL)>1000000000) OR (json_valid(NEW.branch_after)=0 OR json_type(NEW.branch_after) NOT IN ('integer','real') OR NEW.branch_after GLOB '*[^0-9.]*' OR (instr(NEW.branch_after,'.')>0 AND length(NEW.branch_after)-instr(NEW.branch_after,'.')>24) OR CAST(NEW.branch_after AS REAL)<0 OR CAST(NEW.branch_after AS REAL)>1000000000) OR (json_valid(NEW.product_before)=0 OR json_type(NEW.product_before) NOT IN ('integer','real') OR NEW.product_before GLOB '*[^0-9.]*' OR (instr(NEW.product_before,'.')>0 AND length(NEW.product_before)-instr(NEW.product_before,'.')>24) OR CAST(NEW.product_before AS REAL)<0 OR CAST(NEW.product_before AS REAL)>1000000000) OR (json_valid(NEW.product_after)=0 OR json_type(NEW.product_after) NOT IN ('integer','real') OR NEW.product_after GLOB '*[^0-9.]*' OR (instr(NEW.product_after,'.')>0 AND length(NEW.product_after)-instr(NEW.product_after,'.')>24) OR CAST(NEW.product_after AS REAL)<0 OR CAST(NEW.product_after AS REAL)>1000000000) BEGIN SELECT RAISE(ABORT,'epoch command quantity'); END;
